# SRB run 2, R3 and R4 (the first script, srb2.py, was stopped in R3: exact ranks over all pairs too slow).
# R3 as the plan states it: rank from 50-digit values at 40 random directions, threshold 1e-30.
# The algebra generated by a set S is spanned by left-normed brackets [s1,[s2,[...,s_k]]] of elements of S (Jacobi),
# so depth d adds [s, w] for s in S and w a new element of depth d-1.
import sympy as sp, mpmath as mp, random, time
mp.mp.dps = 50
random.seed(790)
x, y, z = sp.symbols('x y z', real=True)
n = sp.Matrix([x, y, z]); E = [sp.eye(3)[:, i] for i in range(3)]
def L(i): return E[i].cross(n)
def X(a, i):
    ni = n.dot(E[i]); return (1 + a * ni**2) * (ni * n - E[i])
def br(A, B): return sp.expand(B.jacobian(n) * A - A.jacobian(n) * B)
pts = []
for _ in range(40):
    v = [mp.mpf(random.gauss(0, 1)) for _ in range(3)]; r = mp.sqrt(sum(t*t for t in v)); pts.append([t / r for t in v])
def vals(F):
    fs = [sp.lambdify((x, y, z), c, 'mpmath') for c in F]
    return [f(*p) for p in pts for f in fs]
def rank(rows):
    if not rows: return 0
    M = mp.matrix(rows); s = mp.svd_r(M, compute_uv=False)
    return sum(1 for t in s if abs(t) > mp.mpf('1e-30') * max(1, abs(s[0])))
def generate(aval, depth, t0):
    S = [L(0), L(1), L(2), X(aval, 0), X(aval, 1), X(aval, 2)]
    rows, basis = [], []
    def add(F):
        r = vals(F)
        if rank(rows + [r]) > len(rows): rows.append(r); basis.append(F); return True
        return False
    for F in S: add(F)
    dims = [len(basis)]; new = list(basis)
    for d in range(depth):
        added = []
        for s in S:
            for w in new:
                C = br(s, w)
                if all(c == 0 for c in C): continue
                if add(C): added.append(C)
        new = added; dims.append(len(basis))
        print('   a=%s depth %d: %d (%.0f s)' % (aval, d + 1, len(basis), time.time() - t0), flush=True)
    return dims
ok = {}
t0 = time.time(); res = {}
for aval in [sp.Integer(0), sp.Integer(1), sp.Rational(1, 2), sp.Rational(-1, 2)]:
    res[aval] = generate(aval, 3, t0)
    print('R3: a = %s, dimension at depth 0..3: %s' % (aval, res[aval]), flush=True)
ok['R3'] = res[0] == [6, 6, 6, 6] and all(res[v][1] > 6 and res[v][1] < res[v][2] < res[v][3]
                                           for v in [sp.Integer(1), sp.Rational(1, 2), sp.Rational(-1, 2)])
# R4: sl(3,R) acting on directions, V_B(n) = Bn - (n.Bn) n, symbolic in the entries of B
Bs = sp.symbols('b0:9', real=True); B = sp.Matrix(3, 3, Bs)
VB = sp.expand(B * n - n.dot(B * n) * n)
def coeff_rows(F):  # linear map B -> F at the points, numerically (the fields are linear in B)
    return [[sp.lambdify((x, y, z), sp.expand(c).coeff(bb), 'mpmath')(*p) for bb in Bs] for p in pts for c in F]
def null(rows):
    M = mp.matrix(rows); U, s, V = mp.svd_r(M)
    k = [i for i in range(V.rows) if i >= len(s) or abs(s[i]) < mp.mpf('1e-30')]
    return [[V[i, j] for j in range(V.cols)] for i in k]
r8 = rank([[t for t in r] for r in zip(*coeff_rows(VB))])  # rank of the 9 fields b_i -> V
so3 = sp.expand(VB.subs(dict(zip(Bs, [0, -1, 0, 1, 0, 0, 0, 0, 0]))) - L(2))
so3_in = all(sp.simplify(c.subs(x**2, 1 - y**2 - z**2)) == 0 for c in sp.expand(so3))
comm = br(L(2), VB)
Sz = sp.diag(1, 1, -1)
mir = Sz * VB.subs({z: -z}, simultaneous=True)                 # (S_* V)(n) = S V(S n), S = S^-1
anti = sp.expand(mir + VB)
Nc = null(coeff_rows(comm))
cf = [sp.expand(VB.subs(dict(zip(Bs, v)))) for v in Nc]
cf_rank = rank([vals(F) for F in cf])
Na = null(coeff_rows(comm) + coeff_rows(anti))
af = [sp.expand(VB.subs(dict(zip(Bs, v)))) for v in Na]
af_rank = rank([vals(F) for F in af]) if af else 0
ok['R4'] = (r8 == 8 and so3_in and cf_rank == 2 and af_rank == 0)
print('R4: rank of the sl(3,R) fields %d; the turn about z among them: %s; commuting with turns about z: rank %d;'
      ' also anti-commuting with z -> -z: rank %d' % (r8, so3_in, cf_rank, af_rank))
print('SUMMARY:', ok)
